var s=`0875-shorshe-ilish`;var a=`world-0875`;var t=`BD`;var n=`south-asia`;var r=4;var o=48;var l={en:`Shorshe Ilish`,ua:`Іліш у гірчичному соусі`};var d={en:`Shorshe Ilish is a Bangladesh dish made with mackerel, serrano pepper, cilantro. This home-scale recipe assigns measured ingredients to the steps where they are used. Mackerel replaces hilsa (ilish); mustard oil and mustard seasoning retain the intended sauce style.`,ua:`Іліш у гірчичному соусі, страва кухні країни Бангладеш. Основні складники: скумбрія, перець серрано, кінза. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Скумбрія замінює іліша (гільсу); гірчична олія й гірчичний соус зберігають характерний смак.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`mackerel`,740,`g`],[`ground-turmeric`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`ground-mustard`,35,`g`],[`mustard-oil`,45,`ml`],[`serrano-pepper`,3,`pcs`],[`water`,200,`ml`]]},{en:`Arrange mustard-marinated mackerel in a heatproof dish and steam until the fish flakes easily and is thoroughly cooked; use food-grade mustard oil.`,ua:`Викладіть скумбрію в гірчичному маринаді у жаростійку миску й готуйте на парі до повної готовності; беріть лише харчову гірчичну олію.`,t:[`steaming`],m:19,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,15,`g`]]}];var m={slug:s,id:a,country:`BD`,region:n,servings:4,minutes:48,title:l,text:d,steps:h};export{t as country,m as default,a as id,o as minutes,n as region,r as servings,s as slug,h as steps,d as text,l as title};